#include "unity.h"
#include "ride_events.h"

void setUp(void)
{
}

void tearDown(void)
{
}

void test_FR_013_01(void)
{
    ride_events_t state;
    bool led_on = false;

    ride_events_init(&state, false);
    state.active[RIDE_SPEEDING] = true;
    state.last_event_ms[RIDE_SPEEDING] = 1000U;

    TEST_ASSERT_EQUAL_INT(RIDE_SPEEDING, ride_events_update(&state, 1000U, &led_on));
    TEST_ASSERT_TRUE(led_on);

    TEST_ASSERT_EQUAL_INT(RIDE_SPEEDING, ride_events_update(&state, 1499U, &led_on));
    TEST_ASSERT_TRUE(led_on);

    TEST_ASSERT_EQUAL_INT(RIDE_SPEEDING, ride_events_update(&state, 1500U, &led_on));
    TEST_ASSERT_FALSE(led_on);

    TEST_ASSERT_EQUAL_INT(RIDE_SPEEDING, ride_events_update(&state, 1999U, &led_on));
    TEST_ASSERT_FALSE(led_on);

    TEST_ASSERT_EQUAL_INT(RIDE_SPEEDING, ride_events_update(&state, 2000U, &led_on));
    TEST_ASSERT_TRUE(led_on);
}
